INSERT INTO `categories` (`id`, `name`, `slug`, `parent_id`, `is_visible`, `description`, `created_at`, `updated_at`, `thumbnail`, `display_type`, `icon_name`) VALUES
(1, 'Phone', 'phone', NULL, 1, 'A phone is a telecommunications device that permits two or more users to conduct a conversation when they are too far apart to be heard directly.', '2024-02-29 14:21:43', '2024-02-29 14:25:31', NULL, 'Products', NULL),
(2, 'Tablet', 'tablet', NULL, 0, 'A tablet computer, commonly shortened to tablet, is a mobile device, typically with a mobile operating system and touchscreen display processing circuitry, and a rechargeable battery in a single, thin and flat package.', '2024-02-29 14:21:43', '2024-02-29 14:21:43', NULL, 'Default', NULL),
(3, 'Laptop', 'laptop', NULL, 0, 'A laptop computer, or simply laptop, is a portable computer which usually weighs 4-8 pounds (2 to 4 kilograms), depending on display size, hardware, and other factors.', '2024-02-29 14:21:43', '2024-02-29 14:32:23', NULL, 'Default', NULL),
(4, 'AC Kantha', 'ac-kantha', NULL, 1, 'Our ac katha is also soft and very comfortable. You can use our ac quilts all over the season.', '2024-02-29 14:23:12', '2024-02-29 15:22:11', '01HQV8J23EHJR95RH7VAJG64WS.jpg', 'Products', NULL),
(5, 'Kitchen Decor items', 'kitchen-decor-items', NULL, 1, 'Our ac Kitchen Decor items is joss.', '2024-02-29 14:23:55', '2024-02-29 15:22:51', '01HQV8KBZYQ8D7Q5KKV0X19YEJ.jpg', 'Products', NULL),
(6, 'Baby Bedding', 'baby-bedding', NULL, 1, 'Baby Bedding will save your life.', '2024-02-29 14:24:36', '2024-02-29 15:23:50', '01HQV8MMSEKX12FNE80T68EQBJ.jpg', 'Products', NULL);
